using System;
using System.IO;
using System.Text;

public class ImageToBase64Converter
{
    public static string ConvertImageToBase64(string filePath)
    {
        try
        {
            // Validate the input file path
            if (string.IsNullOrEmpty(filePath) || !File.Exists(filePath))
            {
                throw new ArgumentException("The file path is invalid or does not exist.", nameof(filePath));
            }

            // Open the file using FileStream and ensure it is disposed of properly
            using (FileStream fileStream = new FileStream(filePath, FileMode.Open, FileAccess.Read))
            {
                // Read the file into a byte array
                byte[] fileBytes = new byte[fileStream.Length];
                int bytesRead = fileStream.Read(fileBytes, 0, fileBytes.Length);

                // Convert the byte array to a Base64 string without line breaks
                string base64String = Convert.ToBase64String(fileBytes, 0, bytesRead);

                return base64String;
            }
        }
        catch (Exception ex)
        {
            // Log the exception or handle it as needed
            Console.WriteLine("An error occurred: " + ex.Message);
            return null;
        }
    }
}

